-- TASK-530 — ninth expert-screened PedMahoratGuli intake batch.
-- Pedagogical mastery, didactics, curriculum documents and methods.
BEGIN;
SET LOCAL lock_timeout='8s'; SET LOCAL statement_timeout='120s';
CREATE TEMP TABLE task530_batch09(
 message_id bigint PRIMARY KEY, construct_code text NOT NULL, lesson_slug text NOT NULL,
 cognitive public.cognitive_level NOT NULL, difficulty integer NOT NULL, stem_md text NOT NULL,
 options jsonb NOT NULL CHECK(jsonb_array_length(options)=4), correct_index integer NOT NULL CHECK(correct_index BETWEEN 0 AND 3),
 explanation_md text NOT NULL, source_reference text GENERATED ALWAYS AS('telegram:@PedMahoratGuli:'||message_id::text||'|task428:expert-rewrite:v1') STORED
) ON COMMIT DROP;
INSERT INTO task530_batch09(message_id,construct_code,lesson_slug,cognitive,difficulty,stem_md,options,correct_index,explanation_md)
SELECT (v->>'m')::bigint,v->>'c',v->>'l',(v->>'k')::public.cognitive_level,(v->>'d')::integer,v->>'s',v->'o',(v->>'a')::integer,v->>'e'
FROM jsonb_array_elements($bank$
[
 {"m":988,"c":"PM.GEN.06","l":"pedagogik-etika-nutq-texnika-va-takt","k":"mulohaza","d":3,"s":"Pedagogik mahorat mazmunini belgilaydigan asosiy belgilarni toping: 1) yuksak madaniyat va bilimdonlik; 2) fan bilimini puxta egallash; 3) pedagogika-psixologiya bilimini qo‘llash; 4) o‘quv-tarbiyaviy metodikani bilish; 5) faqat tadbir tashkil etish.","o":["1, 2 va 3","2, 3 va 5","1, 3 va 5","1, 2, 3 va 4"],"a":3,"e":"Pedagogik mahorat madaniyat, predmet bilimi, pedagogik-psixologik tayyorgarlik va metodikani uyg‘unlashtiradi. Faqat tadbir tashkil etish uning to‘liq mazmunini bermaydi."},
 {"m":989,"c":"PM.GEN.06","l":"pedagogik-etika-nutq-texnika-va-takt","k":"mulohaza","d":3,"s":"Pedagogik mahorat tizimining asosiy komponentlarini belgilang: 1) insonparvar yo‘nalish; 2) kasbiy bilim; 3) ma’muriy vakolat; 4) pedagogik qobiliyat; 5) pedagogik texnika.","o":["1, 2, 4 va 5","2, 3, 4 va 5","1, 3, 4 va 5","1, 2, 3 va 4"],"a":0,"e":"Pedagogik mahoratning asosiy komponentlari insonparvar yo‘nalish, kasbiy bilim, pedagogik qobiliyat va pedagogik texnikadir. Ma’muriy vakolat mahorat komponenti emas."},
 {"m":993,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":2,"s":"Quyidagilardan qaysi biri pedagogik faoliyat tuzilmasining mustaqil tarkibiy qismi sifatida ajratilmaydi?","o":["Pedagogik faoliyat maqsadi","Faoliyat obyekti-subyekti tizimi","Pedagogik faoliyat vositasi","Pedagogik faoliyat vazifasi"],"a":3,"e":"Pedagogik faoliyat tuzilmasida maqsad, subyekt, obyekt, mazmun, vosita va natija ajratiladi. Vazifa maqsadni aniqlashtiradi, lekin bu tasnifda alohida tarkibiy qism emas."},
 {"m":994,"c":"PM.GEN.06","l":"pedagogik-etika-nutq-texnika-va-takt","k":"bilish","d":1,"s":"O‘qituvchining shaxsiy va kasbiy fazilatlarini uyg‘unlashtirib, ta’lim-tarbiyada yuqori natijaga erishishini ta’minlaydigan sifat nima?","o":["Pedagogik texnologiya","Pedagogik mahorat","Pedagogik texnika","Pedagogik odob"],"a":1,"e":"Pedagogik mahorat bilim, qobiliyat, odob, texnika va tajribani uyg‘unlashtirib, kasbiy faoliyatni yuqori darajada amalga oshirish imkonini beradi."},
 {"m":996,"c":"PM.GEN.07","l":"pedagogik-qobiliyat-va-uning-turlari","k":"bilish","d":2,"s":"Kasb va bolalarni sevish, ziyraklik, vazminlik, tashkilotchilik, notiqlik, ilmiy saviya va yangilikka ochiqlik o‘qituvchining qaysi fazilatlar majmuiga kiradi?","o":["Kasbiy fazilatlar majmui","Shaxsiy odatlar majmui","Umuminsoniy fazilatlar majmui","Fiziologik xususiyatlar majmui"],"a":0,"e":"Sanab o‘tilgan belgilar o‘qituvchining kasbiy faoliyatini sifatli bajarishiga xizmat qiladigan shaxsiy-kasbiy fazilatlar majmuini tashkil etadi."},
 {"m":997,"c":"KS.06","l":"oz-ozini-rivojlantirish-va-kasbiy-osish","k":"mulohaza","d":3,"s":"Kasbiy-pedagogik tayyorgarlik yo‘nalishlarini belgilang: 1) shaxsiy fazilatlar; 2) ruhiy-psixologik tayyorgarlik; 3) ijtimoiy-pedagogik va ilmiy-nazariy tayyorgarlik; 4) sport tayyorgarligi; 5) ixtisoslik metodikasi.","o":["1, 2, 4 va 5","2, 3, 4 va 5","1, 2, 3 va 5","1, 2, 3 va 4"],"a":2,"e":"Kasbiy tayyorgarlik shaxsiy, psixologik, ijtimoiy-pedagogik, ilmiy-nazariy va ixtisoslik-metodik yo‘nalishlarni qamrab oladi. Sport tayyorgarligi umumiy majburiy yo‘nalish emas."},
 {"m":1031,"c":"PM.GEN.07","l":"pedagogik-qobiliyat-va-uning-turlari","k":"qollash","d":2,"s":"Pedagogning so‘zi, ovozi va tana harakati o‘zaro uyg‘un; o‘quvchilar uning harakatlari orqali mazmunni tez anglaydi. Qaysi qobiliyat ko‘proq namoyon?","o":["Anglash qobiliyati","Bilish qobiliyati","Kinestetik qobiliyat","Bashoratlash qobiliyati"],"a":2,"e":"Tana harakati, fazoviy ifoda va jismoniy namoyishni mazmun bilan uyg‘unlashtira olish kinestetik qobiliyatning amaliy belgisi hisoblanadi."},
 {"m":1032,"c":"PM.GEN.07","l":"pedagogik-qobiliyat-va-uning-turlari","k":"qollash","d":2,"s":"Sinf rahbari tadbirlarni hamkorlikda tashkil etadi, sinfda ijobiy ruh va madaniyatli munosabat qaror topgan. Qaysi qobiliyat ustuvor?","o":["Muloqot qobiliyati","Bilish qobiliyati","Kinestetik qobiliyat","Bashoratlash qobiliyati"],"a":0,"e":"Ijobiy munosabat, hamkorlik va sog‘lom ruhni shakllantirish samarali muloqot o‘rnatish qobiliyati bilan bevosita bog‘liq."},
 {"m":1034,"c":"PM.GEN.07","l":"pedagogik-qobiliyat-va-uning-turlari","k":"qollash","d":3,"s":"O‘qituvchi o‘quvchilar imkoniyatini oldindan baholab, tadbir rollarini mos taqsimladi va kutilgan natijaga erishdi. Qaysi qobiliyat ustuvor?","o":["Muloqot qobiliyati","Bilish qobiliyati","Kinestetik qobiliyat","Bashoratlash qobiliyati"],"a":3,"e":"O‘quvchi imkoniyatiga tayangan holda faoliyat natijasini oldindan ko‘rish va vazifalarni shunga mos belgilash pedagogik bashoratlash qobiliyatini ko‘rsatadi."},
 {"m":1035,"c":"PM.GEN.07","l":"pedagogik-qobiliyat-va-uning-turlari","k":"qollash","d":2,"s":"O‘qituvchi loyiha xarajatlarini murakkab hisob-kitob orqali asoslab, amaliy cheklovlarni mantiqiy izohladi. Qaysi qobiliyat ko‘proq namoyon?","o":["Muloqot qobiliyati","Shaxsiy qobiliyat","Mantiqiy qobiliyat","Bashoratlash qobiliyati"],"a":2,"e":"Hisob-kitob, sabab-oqibat bog‘lanishi va amaliy cheklovlarni izchil asoslash mantiqiy fikrlash qobiliyatining bevosita namoyonidir."},
 {"m":1041,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":1,"s":"Bilim va tajribaga tayangan holda muayyan ishni ongli ravishda bajarish usuli qanday ataladi?","o":["Amaliy malaka","Kasbiy ko‘nikma","Tabiiy iste’dod","Shaxsiy qobiliyat"],"a":1,"e":"Ko‘nikma bilim va tajribaga asoslanib ishni ongli bajarish usulidir. Malaka esa ko‘p mashq natijasida avtomatlashgan bajarishni bildiradi."},
 {"m":1100,"c":"PM.GEN.07","l":"pedagogik-qobiliyat-va-uning-turlari","k":"bilish","d":1,"s":"Pedagog o‘z kasbini mohirona bajarish bilan birga turli boshqa faoliyatlarda ham muvaffaqiyat qozonsa, unda qaysi qobiliyat rivojlangan?","o":["Umumiy qobiliyat","Maxsus qobiliyat","Xususiy qobiliyat","Shaxsiy odat"],"a":0,"e":"Ko‘plab faoliyat turlarida muvaffaqiyatni ta’minlaydigan tafakkur, o‘rganish va moslashish imkoniyatlari umumiy qobiliyatga kiradi."},
 {"m":1172,"c":"PM.GEN.07","l":"pedagogik-qobiliyat-va-uning-turlari","k":"qollash","d":2,"s":"O‘qituvchi tadbir mazmunini yorituvchi taqdimot va o‘quvchilar ishtirokidagi videoni yaxlit kompozitsiya sifatida yaratdi. Qaysi qobiliyat ustuvor?","o":["Didaktik qobiliyat","Akademik qobiliyat","Konstruktiv qobiliyat","Tashkilotchilik qobiliyati"],"a":2,"e":"Turli material va vositalarni yagona maqsadga yo‘naltirilgan tuzilma sifatida loyihalash konstruktiv qobiliyatning amaliy namoyonidir."},
 {"m":1175,"c":"PM.GEN.07","l":"pedagogik-qobiliyat-va-uning-turlari","k":"qollash","d":2,"s":"Pedagog ta’lim-tarbiya qonuniyatlariga tayanadi va jarayon mohiyatini chuqur tushunib, faoliyatini asosli tashkil etadi. Qaysi qobiliyat namoyon?","o":["Anglash qobiliyati","Kommunikativ qobiliyat","Didaktik qobiliyat","Konstruktiv qobiliyat"],"a":0,"e":"Pedagogik qonuniyatlar va jarayon mohiyatini chuqur tushunib faoliyatda hisobga olish anglash qobiliyatining asosiy ko‘rsatkichidir."},
 {"m":1389,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":2,"s":"Ilmiy hamjamiyat muammoni ko‘rish va hal qilish uchun ma’lum davrda qabul qilgan nazariya, mezon va namunalar tizimi nima deyiladi?","o":["Ilmiy paradigma","Didaktik vosita","Ta’lim metodi","O‘rganish jarayoni"],"a":0,"e":"Paradigma ilmiy hamjamiyat tomonidan muayyan davrda tan olingan nazariy qarashlar, muammo qo‘yish usullari va yechim namunalarining yaxlit tizimidir."},
 {"m":1395,"c":"PM.GEN.02","l":"pedagogikaning-asosiy-tamoyillari","k":"bilish","d":2,"s":"Ta’lim qonuniyati tushunchasining eng aniq ta’rifi qaysi?","o":["Shaxs dunyoqarashini shakllantiradigan tarbiyaviy natija","Mazmun va metodni belgilaydigan boshlang‘ich qoida","O‘qituvchi hamda o‘quvchining maqsadli faoliyati","Ta’lim qismlari orasidagi obyektiv va takrorlanuvchi aloqa"],"a":3,"e":"Ta’lim qonuniyati jarayonning tarkibiy qismlari o‘rtasida mavjud bo‘lgan obyektiv, barqaror va takrorlanuvchi muhim aloqani anglatadi."},
 {"m":1403,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":1,"s":"O‘qitish jarayonining uch asosiy vazifasi qaysi?","o":["Ta’limiy, tashkiliy va rivojlantiruvchi","Ta’limiy, tarbiyaviy va rivojlantiruvchi","Ta’limiy, tarbiyaviy va tashkiliy","Shakllantiruvchi, tarbiyaviy va nazorat qiluvchi"],"a":1,"e":"O‘qitish jarayoni bilim va kompetensiya beruvchi ta’limiy, qadriyat va xulqni shakllantiruvchi tarbiyaviy hamda tafakkurni o‘stiruvchi rivojlantiruvchi vazifalarni bajaradi."},
 {"m":1404,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":2,"s":"O‘qitishning ta’limiy vazifasi qaysi natijaga qaratiladi?","o":["Bilim, ko‘nikma, malaka va kompetensiyalarni shakllantirishga","Ma’naviy-axloqiy qarash va xulqni shakllantirishga","Nutq, tafakkur va hissiy-irodaviy sifatlarni rivojlantirishga","Ta’lim ishtirokchilarining birgalikdagi faoliyatini tashkil etishga"],"a":0,"e":"Ta’limiy vazifa o‘quvchida tizimli bilim, ko‘nikma, malaka va kompetensiyalarni shakllantirish hamda ularni amalda qo‘llashga tayyorlashga qaratiladi."},
 {"m":1405,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":2,"s":"O‘qitishning rivojlantiruvchi vazifasi qaysi natijada namoyon bo‘ladi?","o":["Ma’naviy-axloqiy qarash va xulq shakllanishida","O‘qituvchi va o‘quvchi hamkorligi tashkil etilishida","Bilim, ko‘nikma va kompetensiyalar egallanishida","Nutq, tafakkur va hissiy-irodaviy sifatlar rivojlanishida"],"a":3,"e":"Rivojlantiruvchi vazifa o‘quvchining nutqi, tafakkuri, sezgi-harakat sohasi, intellektual va hissiy-irodaviy sifatlarini o‘stirishga qaratiladi."},
 {"m":1406,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":3,"s":"Bilimni o‘zlashtirish bosqichlarining to‘g‘ri ketma-ketligini toping.","o":["Idrok etish → mustahkamlash → amalda qo‘llash → baholash","Idrok etish → tushunish → rivojlantirish → nazorat qilish","Idrok etish → tushunish → mustahkamlash → amalda qo‘llash","Rivojlantirish → tushunish → mustahkamlash → amalda qo‘llash"],"a":2,"e":"O‘zlashtirish avval materialni idrok etish, keyin anglash va tushuncha hosil qilish, so‘ng mustahkamlash hamda amaliy qo‘llash bosqichlarida kechadi."},
 {"m":1436,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":1,"s":"O‘quvchilar egallashi lozim bo‘lgan bilim, ko‘nikma, malaka va kompetensiyalarning belgilangan hajmi hamda ko‘lami nima?","o":["Ta’lim jarayoni","Ta’lim mazmuni","Ta’lim maqsadi","Ta’lim metodi"],"a":1,"e":"Ta’lim mazmuni jamiyat va standart talablariga muvofiq o‘quvchi egallashi lozim bo‘lgan bilim, ko‘nikma, malaka va kompetensiyalar tizimidir."},
 {"m":1441,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":1,"s":"Umumiy o‘rta ta’lim mazmuniga qo‘yiladigan asosiy davlat talablarini belgilaydigan me’yoriy hujjat qaysi?","o":["O‘quv dasturi","Tayanch o‘quv reja","Davlat ta’lim standarti","Malaka talablari"],"a":2,"e":"Davlat ta’lim standarti ta’lim mazmuni va sifatiga qo‘yiladigan majburiy davlat talablarini belgilaydi; reja va dasturlar unga tayangan holda tuziladi."},
 {"m":1442,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":2,"s":"Davlat ta’lim standartining bosh maqsadi qaysi javobda to‘g‘ri ifodalangan?","o":["Zamonaviy talabda sifatli ta’lim va barkamol shaxsni ta’minlash","Fanlar nomi va haftalik yuklama miqdorini taqsimlash","Mavzular hajmi va o‘rganish ketma-ketligini yozish","Bilim, ko‘nikma va malaka atamalarini izohlash"],"a":0,"e":"Standartning bosh maqsadi ijtimoiy ehtiyoj, ilg‘or tajriba va zamonaviy fan-texnika asosida sifatli ta’limni hamda barkamol shaxs rivojini ta’minlashdir."},
 {"m":1444,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":1,"s":"Fanlar nomi, minimal o‘quv yuklamasi va uning sinflar bo‘yicha taqsimotini belgilaydigan hujjat qaysi?","o":["Davlat ta’lim standarti","Tayanch o‘quv reja","Umumiy o‘quv dasturi","Malaka talablari"],"a":1,"e":"Tayanch o‘quv reja umumiy o‘rta ta’limda o‘qitiladigan fanlar ro‘yxati, minimal yuklama va uning sinflar bo‘yicha taqsimotini belgilaydi."},
 {"m":1446,"c":"PM.GEN.04","l":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","k":"bilish","d":1,"s":"Tayanch reja asosida fan mavzulari hajmi, mazmuni, ketma-ketligi va shakllantiriladigan kompetensiyalarni belgilaydigan hujjat qaysi?","o":["Davlat ta’lim standarti","Tayanch o‘quv reja","O‘quv dasturi","Malaka talablari"],"a":2,"e":"O‘quv dasturi muayyan fan bo‘yicha mavzular mazmuni, hajmi, o‘rganish ketma-ketligi va kutiladigan kompetensiyalarni aniq belgilaydi."},
 {"m":1471,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"bilish","d":1,"s":"Metod atamasining kelib chiqishi va ma’nosi qaysi javobda to‘g‘ri berilgan?","o":["Lotincha tartib va boshqarish yo‘li","Inglizcha izlanish va tajriba usuli","Yunoncha o‘qitish va nazorat usuli","Yunoncha tadqiqot va maqsadga erishish yo‘li"],"a":3,"e":"Metod yunoncha methodos so‘zidan kelib chiqqan bo‘lib, tadqiq etish, bilish yoki maqsadga erishish yo‘li ma’nosini anglatadi."},
 {"m":1472,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"bilish","d":1,"s":"Ta’lim usuli tushunchasining eng aniq ta’rifi qaysi?","o":["O‘qituvchi va o‘quvchi faoliyatini tashkil etadigan metodlar majmui","Metodning muayyan vazifani hal qiladigan tarkibiy qismi","Natijani kafolatlashga qaratilgan yaxlit pedagogik jarayon","Maqsadga erishishning umumiy yo‘nalishi va tamoyili"],"a":1,"e":"Usul metodning tarkibiy qismi yoki alohida tomoni bo‘lib, uning yordamida umumiy o‘quv vazifasining muayyan qismi hal etiladi."},
 {"m":1473,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"bilish","d":1,"s":"Ta’lim metodi tushunchasining eng aniq ta’rifi qaysi?","o":["Didaktik vazifani hamkorlikda hal etish yo‘li","Metod ichida qo‘llanadigan alohida amaliy harakat","Natijani kafolatlaydigan bosqichli texnologik loyiha","Darsda foydalaniladigan moddiy va raqamli vosita"],"a":0,"e":"Ta’lim metodi o‘qituvchi faoliyati va o‘quvchining o‘quv-bilish faoliyatini didaktik maqsadga erishish uchun o‘zaro bog‘liq tashkil etish yo‘lidir."},
 {"m":1474,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"bilish","d":1,"s":"Pedagogik texnologiya odatda nechta asosiy qo‘llanish darajasida ko‘rib chiqiladi?","o":["Ikki darajada","Uch darajada","To‘rt darajada","Besh darajada"],"a":1,"e":"Pedagogik texnologiya umumiy pedagogik, xususiy metodik va lokal-modul darajalarida ko‘rib chiqiladi; ular qamrov ko‘lami bilan farqlanadi."},
 {"m":1475,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"bilish","d":2,"s":"Pedagogik texnologiyaga berilgan eng aniq ta’rifni toping.","o":["Ta’lim natijasini tizimli loyihalash va boshqarish jarayoni","O‘qituvchi nutqiga asoslangan an’anaviy tushuntirish usuli","O‘quvchining natijasini qayd etadigan nazorat vositasi","Darsda qo‘llanadigan ko‘rgazmali materiallar to‘plami"],"a":0,"e":"Pedagogik texnologiya maqsad, mazmun, metod, vosita, jarayon va baholashni o‘zaro bog‘lab, rejalashtirilgan natijaga erishishni tizimli loyihalash va amalga oshirishdir."}
]
$bank$::jsonb) AS source(v);

DO $task530_b09$
DECLARE b task530_batch09%rowtype; actor uuid; subject_id uuid; construct_id uuid; lesson_id uuid; question_id uuid; option_id uuid; option_ids uuid[]; i integer; n integer; bad integer; bad_id uuid; bad_code text; bad_source text;
BEGIN
 IF (SELECT count(*) FROM task530_batch09)<>30 THEN RAISE EXCEPTION 'TASK530_B09_COUNT'; END IF;
 IF EXISTS(SELECT 1 FROM task530_batch09 tb JOIN public.questions q ON q.source_reference='telegram:@PedMahoratGuli:'||tb.message_id::text OR q.source_reference LIKE 'telegram:@PedMahoratGuli:'||tb.message_id::text||'|%') THEN RAISE EXCEPTION 'TASK530_B09_SOURCE_ALREADY_REPRESENTED'; END IF;
 SELECT id INTO STRICT actor FROM public.profiles WHERE role='admin' AND NOT coalesce(is_blocked,false);
 IF (SELECT count(*) FROM public.profiles WHERE role='admin' AND NOT coalesce(is_blocked,false))<>1 THEN RAISE EXCEPTION 'TASK530_B09_OWNER_NOT_UNIQUE'; END IF;
 SELECT id INTO STRICT subject_id FROM public.subjects WHERE code='informatika'; CREATE TEMP TABLE task530_b09_ids(id uuid PRIMARY KEY) ON COMMIT DROP;
 FOR b IN SELECT * FROM task530_batch09 ORDER BY message_id LOOP
  SELECT c.id,l.id INTO STRICT construct_id,lesson_id FROM public.constructs c JOIN public.lesson_constructs lc ON lc.construct_id=c.id JOIN public.lessons l ON l.id=lc.lesson_id WHERE c.code=b.construct_code AND c.is_active AND l.slug=b.lesson_slug AND l.status='published'::public.content_status;
  IF EXISTS(SELECT 1 FROM public.questions q WHERE q.status IN('review','published') AND regexp_replace(lower(btrim(q.stem_md)),'[^[:alnum:]]+','','g')=regexp_replace(lower(btrim(b.stem_md)),'[^[:alnum:]]+','','g')) THEN RAISE EXCEPTION 'TASK530_B09_ACTIVE_EXACT_DUPLICATE_%',b.message_id; END IF;
  question_id:=gen_random_uuid(); INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,author_id,is_generated,source_lesson_id,source_reference) VALUES(question_id,subject_id,construct_id,CASE WHEN b.construct_code LIKE 'KS.%' THEN 'KS' ELSE 'PM.GEN' END,'Y1'::public.question_format,b.cognitive,b.difficulty,b.stem_md,'review'::public.content_status,NULL,true,lesson_id,b.source_reference); INSERT INTO task530_b09_ids VALUES(question_id); option_ids:=ARRAY[]::uuid[];
  FOR i IN 0..3 LOOP option_id:=gen_random_uuid(); option_ids:=array_append(option_ids,option_id); INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(option_id,question_id,'a',i,b.options->>i); END LOOP;
  INSERT INTO public.question_keys(question_id,payload,explanation_md) VALUES(question_id,jsonb_build_object('correct_option_id',option_ids[b.correct_index+1]),b.explanation_md);
 END LOOP;
 WITH checks AS(SELECT q.id,count(o.id) option_count,count(DISTINCT lower(btrim(o.content_md))) distinct_count,count(*) FILTER(WHERE o.id::text=k.payload->>'correct_option_id') correct_count,min(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) minw,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) maxw,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) FILTER(WHERE o.id::text=k.payload->>'correct_option_id') correctw,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) FILTER(WHERE o.id::text<>k.payload->>'correct_option_id') maxwrong FROM task530_b09_ids r JOIN public.questions q ON q.id=r.id JOIN public.question_options o ON o.question_id=q.id AND btrim(o.side)='a' JOIN public.question_keys k ON k.question_id=q.id GROUP BY q.id) SELECT count(*) FILTER(WHERE option_count<>4 OR distinct_count<>4 OR correct_count<>1 OR minw<1 OR maxw>minw*1.8 OR correctw>maxwrong*1.25),count(*) INTO bad,n FROM checks;
 IF bad<>0 OR n<>30 THEN RAISE EXCEPTION 'TASK530_B09_BALANCE_%_COUNT_%',bad,n; END IF;
 INSERT INTO public.pedagogy_owner_release_waivers(question_id,authorized_by,content_fingerprint,authority,provenance) SELECT q.id,actor,public.professional_question_fingerprint(q.id),'owner_explicit_no_external_expert_20261018','TASK-530 batch 09; owner-delegated AI expert rewrite of PedMahoratGuli mastery/didactics items; key independently checked; independent human expert signoff NOT claimed' FROM task530_b09_ids r JOIN public.questions q ON q.id=r.id;
 GET DIAGNOSTICS n=ROW_COUNT; IF n<>30 THEN RAISE EXCEPTION 'TASK530_B09_WAIVERS_%',n; END IF;
 SELECT r.id,q.source_reference,s.finding_code INTO bad_id,bad_source,bad_code FROM task530_b09_ids r JOIN public.questions q ON q.id=r.id CROSS JOIN LATERAL public.pedagogy_semantic_quality_signals(r.id) s WHERE s.severity='high' ORDER BY r.id,s.finding_code LIMIT 1;
 IF bad_id IS NOT NULL THEN RAISE EXCEPTION 'TASK530_B09_SEMANTIC_%_%',bad_source,bad_code; END IF;
 UPDATE public.questions q SET status='published'::public.content_status,updated_at=now() FROM task530_b09_ids r WHERE q.id=r.id AND q.status='review'::public.content_status; GET DIAGNOSTICS n=ROW_COUNT; IF n<>30 THEN RAISE EXCEPTION 'TASK530_B09_PUBLISHED_%',n; END IF;
 SELECT count(*) INTO n FROM task530_b09_ids r JOIN public.questions q ON q.id=r.id JOIN public.pedagogy_owner_release_waivers w ON w.question_id=q.id JOIN public.pedagogy_published_revisions p ON p.question_id=q.id WHERE q.status='published'::public.content_status AND w.content_fingerprint=public.professional_question_fingerprint(q.id); IF n<>30 THEN RAISE EXCEPTION 'TASK530_B09_POSTFLIGHT_%_OF_30',n; END IF;
END $task530_b09$;
COMMIT;
